CREATE TABLE `fee_types` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb3_unicode_ci NOT NULL,
  `applicable_class` varchar(191) COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'All',
