INSERT INTO `lesson_plans` VALUES (1,'Introduction to Electromagnetic Waves',5,9,2,'Week 20 (May 12–16)','Monday',1,'45 mins','[\"Define electromagnetic waves and their properties\", \"Identify the electromagnetic spectrum\", \"Explain wave-particle duality\"]','[\"Interactive lecture with diagrams\", \"Group discussion on real-world applications\", \"Short video: EM spectrum visualisation\"]','[\"Physics Textbook Ch. 14\", \"Projector\", \"EM spectrum chart\"]','Read Ch. 14 pages 201–210. Answer questions 1–5.','completed','2026/Term 1','SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(2,'Laws of Reflection and Plane Mirrors',5,9,2,'Week 20 (May 12–16)','Wednesday',3,'45 mins','[\"State the laws of reflection\", \"Distinguish between regular and diffuse reflection\", \"Solve ray diagram problems\"]','[\"Demonstration with mirrors and laser pointer\", \"Guided practice problems\", \"Pair work: ray diagrams\"]','[\"Plane mirrors\", \"Laser pointer\", \"Protractor\", \"Worksheet 14.2\"]','Complete worksheet 14.2. Draw 3 ray diagrams.','published','2026/Term 1','SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(3,'Refraction and Snell\'s Law',5,9,2,'Week 21 (May 19–23)','Monday',1,'45 mins','[\"Define refraction and refractive index\", \"Apply Snell\'s law to solve problems\", \"Explain total internal reflection\"]','[\"Lab demonstration: light through glass block\", \"Derivation of Snell\'s law\", \"Practice calculations\"]','[\"Glass block\", \"Ray box\", \"Protractor\", \"Calculator\"]','Solve problems 1–8 on page 225.','draft','2026/Term 1','SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16');
/*!40000 ALTER TABLE `lesson_plans` ENABLE KEYS */;
UNLOCK TABLES;

