INSERT INTO `messages` VALUES (1,1,'staff',2,'Update on Kehinde\'s Performance','Dear Parent,\n\nI wanted to share a brief update on Kehinde\'s progress in Physics this term. Overall performance has been satisfactory, though there is room for improvement in the optics section. Please encourage more study time at home.\n\nBest regards,\nMr. Okafor',0,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(2,2,'staff',2,'Update on Funmi\'s Performance','Dear Parent,\n\nI wanted to share a brief update on Funmi\'s progress in Physics this term. Overall performance has been satisfactory, though there is room for improvement in the optics section. Please encourage more study time at home.\n\nBest regards,\nMr. Okafor',0,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(3,3,'staff',2,'Update on Ifeoma\'s Performance','Dear Parent,\n\nI wanted to share a brief update on Ifeoma\'s progress in Physics this term. Overall performance has been satisfactory, though there is room for improvement in the optics section. Please encourage more study time at home.\n\nBest regards,\nMr. Okafor',0,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16');
