INSERT INTO `notices` VALUES (1,'End of Term Examination Schedule Released','ALL STAFF & STUDENTS','The First Term examination timetable has been uploaded to the student portal. All students in JSS 1 through SSS 3 should download and prepare accordingly. Examinations begin on the 14th of June, 2026.',1,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(2,'Staff Development Workshop — June 2026','FACULTY ONLY','All teaching staff are required to attend the scheduled professional development workshop on Saturday, June 7th. Attendance is compulsory. Venue: School Hall. Time: 9:00 AM.',0,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(3,'WAEC Registration Deadline — SSS 3','SSS 3 STUDENTS','All SSS 3 students who have not completed their WAEC registration must do so by Friday, May 30, 2026. Failure to register before the deadline may affect sitting the examinations.',0,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16'),(4,'PTA Meeting — Saturday 31st May','ALL PARENTS & STAFF','Parents are invited to the quarterly PTA meeting on Saturday 31st May, 2026 at 10:00 AM. Agenda includes school fees review, student performance report, and plans for the upcoming Sports Day.',1,'SCH-001','2026-05-29 05:52:16','2026-05-29 05:52:16');
/*!40000 ALTER TABLE `notices` ENABLE KEYS */;
UNLOCK TABLES;

