--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `students` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `student_id` varchar(191) COLLATE utf8mb3_unicode_ci NOT NULL,
  `admission_no` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `first_name` varchar(191) COLLATE utf8mb3_unicode_ci NOT NULL,
  `last_name` varchar(191) COLLATE utf8mb3_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `phone` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `address` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `gender` enum('Male','Female') COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `class_section_id` bigint unsigned DEFAULT NULL,
  `parent_name` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `parent_phone` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `parent_email` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `grade` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `section` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `school_id` varchar(191) COLLATE utf8mb3_unicode_ci NOT NULL,
  `status` enum('active','inactive','graduated','transferred') COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'active',
  `enrollment_date` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `students_student_id_unique` (`student_id`),
  UNIQUE KEY `students_email_unique` (`email`),
  KEY `students_user_id_foreign` (`user_id`),
  KEY `students_class_section_id_foreign` (`class_section_id`),
  CONSTRAINT `students_class_section_id_foreign` FOREIGN KEY (`class_section_id`) REFERENCES `class_sections` (`id`) ON DELETE SET NULL,
  CONSTRAINT `students_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=376 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

